// ─── File: ConnectDemo.java ───
package com.bank.connect;

import java.util.logging.*;

public class ConnectDemo {
    private static final Logger log = Logger.getLogger("Connect");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        ConnectionAdvisor advisor = new ConnectionAdvisor();
        ConnectionPlan linux = advisor.plan("LINUX", "ec2-user", "nbi-settlement-key.pem");
        ConnectionPlan windows = advisor.plan("WINDOWS", "Administrator", "nbi-settlement-key.pem");

        log.info(() -> "Linux:   " + linux);
        log.info(() -> "Windows: " + windows);

        KeyFileGuard guard = new KeyFileGuard();
        boolean safe = guard.permissionsSafe("r--------");   // 0400
        boolean unsafe = guard.permissionsSafe("rw-rw-rw-"); // world readable
        log.info(() -> "Key with 0400 is safe to use: " + safe);
        log.warning(() -> "Key world-readable is safe: " + unsafe);
    }
}

// ─── Would be in ConnectionPlan.java ───
class ConnectionPlan {
    final String protocol; final int port; final String recipe;
    ConnectionPlan(String protocol, int port, String recipe) {
        this.protocol = protocol; this.port = port; this.recipe = recipe;
    }
    @Override public String toString() { return protocol + " on port " + port + " — " + recipe; }
}

// ─── Would be in ConnectionAdvisor.java ───
class ConnectionAdvisor {
    ConnectionPlan plan(String os, String user, String keyFile) {
        return switch (os) {
            case "LINUX" -> new ConnectionPlan("SSH", 22,
                    "ssh -i " + keyFile + " " + user + "@<host>");
            case "WINDOWS" -> new ConnectionPlan("RDP", 3389,
                    "decrypt Administrator password with " + keyFile + ", then RDP as " + user);
            default -> throw new IllegalArgumentException("Unknown OS: " + os);
        };
    }
}

// ─── Would be in KeyFileGuard.java ───
class KeyFileGuard {
    // SSH refuses a private key that is readable by others.
    boolean permissionsSafe(String symbolic) {
        return symbolic.equals("r--------") || symbolic.equals("rw-------");
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), r.getMessage());
    }
}
